import {getInstrument} from './catalog.js';
import {ART} from './instrument-art.js';
import {syncSection,songBars,createSection,appendSection,activateSection,deleteSection,moveEntry} from './song.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const openEntries=new Set();
export function renderSong(container,p,{change,edit,play,confirm}){
 syncSection(p);
 const bars=songBars(p),seconds=bars*Number(p.meter.split('/')[0])*4/Number(p.meter.split('/')[1])*60/p.bpm;
 const rounded=Math.round(seconds),duration=Math.floor(rounded/60)+':'+String(rounded%60).padStart(2,'0');
 let at=1;
 container.innerHTML=`<div class="view-header"><div><div class="eyebrow">COMPOSITION WORKSPACE</div><h1>Song Builder</h1><p>Give your ideas a beginning, a journey, and a return.</p></div><div class="view-tools"><button class="brass" id="play-song" ${bars?'':'disabled'}>▶ Play song</button></div></div>
 <div class="song-overview"><div><span class="eyebrow">YOUR SONG FORM</span><strong>${bars}<small> measures</small><span> · </span>${duration}</strong><p>${p.meter} · ♩ = ${p.bpm} · One pass, before sound tails</p></div><div class="form-ribbon" aria-label="Song form">${p.arrangement.map(e=>{const s=p.sections.find(s=>s.id===e.section),n=p.sections.indexOf(s);return `<button class="form-block section-color-${n%4}" data-form-jump="${e.id}" style="flex-grow:${s.bars*e.repeats}" title="${esc(s.name)} · ${s.bars*e.repeats} measures"><strong>${esc(s.name)}</strong><small>${e.repeats>1?'× '+e.repeats:s.bars+' bars'}</small></button>`}).join('')||'<span class="form-empty">Add a section below to begin your song.</span>'}</div></div>
 <div class="song-layout"><aside class="section-library"><div class="song-panel-heading"><div><span class="eyebrow">REUSABLE SECTIONS</span><h2>Your musical ideas</h2></div><button class="outline" id="new-section" ${p.sections.length>=32?'disabled':''}>+ New</button></div><p class="song-hint">Reuse a section to keep its notes linked. Make a variation for an independent copy.</p>
 ${p.sections.map((s,n)=>{const notes=Object.values(s.events).reduce((sum,events)=>sum+events.length,0),uses=p.arrangement.filter(e=>e.section===s.id).length;return `<article class="section-card ${p.activeSection===s.id?'current':''} section-color-${n%4}"><div class="section-card-top"><span class="section-swatch"></span><input data-section-name="${s.id}" value="${esc(s.name)}" maxlength="40" aria-label="Section name, ${esc(s.name)}"><span class="section-current">${p.activeSection===s.id?'EDITING':''}</span></div><p>${s.bars} bars · ${notes} notes · ${uses} ${uses===1?'appearance':'appearances'}</p><div class="section-card-actions"><button class="outline" data-edit-section="${s.id}">Edit notes ↗</button><button class="outline" data-add-section="${s.id}">+ Add to song</button></div><div class="section-card-foot"><button class="quiet" data-copy-section="${s.id}" ${p.sections.length>=32?'disabled':''}>Make variation</button><button class="quiet remove" data-delete-section="${s.id}" aria-label="Delete section ${esc(s.name)}" ${p.sections.length===1?'disabled':''}>Delete</button></div></article>`}).join('')}</aside>
 <section class="song-form"><div class="song-panel-heading"><div><span class="eyebrow">PLAYING ORDER</span><h2>Arrange the ensemble</h2></div><span class="song-count">${p.arrangement.length} ${p.arrangement.length===1?'appearance':'appearances'}</span></div><p class="song-hint">Drag a handle or use the arrows to reorder. Entrances apply to this appearance only.</p><div class="song-entries">${p.arrangement.map((e,index)=>{const s=p.sections.find(s=>s.id===e.section),n=p.sections.indexOf(s),first=at;at+=s.bars*e.repeats;const playing=p.tracks.filter(t=>s.events[t.id]?.length),count=playing.filter(t=>!e.mutedTracks.includes(t.id)).length;
 return `<article class="song-entry section-color-${n%4}" data-entry="${e.id}" tabindex="-1"><div class="entry-heading"><button class="drag-handle" draggable="true" data-drag-entry="${e.id}" aria-label="Drag ${esc(s.name)} to reorder" title="Drag to reorder">⠿</button><span class="entry-number">${String(index+1).padStart(2,'0')}</span><div class="entry-name"><strong>${esc(s.name)}</strong><small>Measures ${first}–${at-1} · ${s.bars} bars per pass</small></div><label class="repeat-control">PLAYS<select data-repeat-entry="${e.id}" aria-label="Number of plays for appearance ${index+1}">${Array.from({length:16},(_,r)=>`<option value="${r+1}" ${e.repeats===r+1?'selected':''}>${r+1}×</option>`).join('')}</select></label></div><div class="entry-actions"><button class="quiet" data-edit-section="${s.id}">Edit section ↗</button><span></span><button class="quiet" data-move-entry="${e.id}" data-delta="-1" aria-label="Move appearance ${index+1} up" ${index===0?'disabled':''}>↑</button><button class="quiet" data-move-entry="${e.id}" data-delta="1" aria-label="Move appearance ${index+1} down" ${index===p.arrangement.length-1?'disabled':''}>↓</button><button class="quiet remove" data-remove-entry="${e.id}" aria-label="Remove appearance ${index+1} from song">Remove</button></div><details data-entrances="${e.id}" ${openEntries.has(e.id)?'open':''}><summary><span>Instrument entrances</span><small>${playing.length?count+' of '+playing.length+' parts':'No notes in this section yet'}</small></summary><div class="entrance-parts">${p.tracks.map(t=>{const hasNotes=!!s.events[t.id]?.length,included=!e.mutedTracks.includes(t.id),i=getInstrument(t.instrument);return `<label class="entrance-part ${included?'included':''} ${hasNotes?'':'empty-part'}"><input type="checkbox" data-entrance-entry="${e.id}" data-part="${t.id}" ${included?'checked':''} ${hasNotes?'':'disabled'}><img src="${ART[i.id].src}" alt="" loading="lazy"><span>${esc(t.name)}<small>${!hasNotes?'No notes':t.muted?'Muted in ensemble mix':p.tracks.some(t=>t.solo)&&!t.solo?'Another part is soloed':included?'Plays in this appearance':'Rests in this appearance'}</small></span></label>`}).join('')||'<p class="song-hint">Choose instruments from the Collection to build your ensemble.</p>'}</div></details></article>`}).join('')||'<div class="song-empty"><span>♪</span><h3>The form is yours.</h3><p>Use “Add to song” beside any section. Bring an idea back as often as you like.</p></div>'}</div><p class="song-footnote">Section names and entrances carry through to your full-song score and exports. Tempo, meter and the ensemble mix are shared.</p></section></div>`;
 const $=s=>container.querySelector(s),$$=s=>[...container.querySelectorAll(s)];
 $('#play-song').onclick=play;
 $('#new-section').onclick=()=>change(()=>{const s=createSection(p);appendSection(p,s.id);activateSection(p,s.id)});
 $$('[data-section-name]').forEach(input=>input.onchange=()=>change(()=>{p.sections.find(s=>s.id===input.dataset.sectionName).name=input.value.trim().slice(0,40)||'Untitled section'}));
 $$('[data-edit-section]').forEach(b=>b.onclick=()=>edit(b.dataset.editSection));
 $$('[data-add-section]').forEach(b=>b.onclick=()=>change(()=>appendSection(p,b.dataset.addSection)));
 $$('[data-copy-section]').forEach(b=>b.onclick=()=>change(()=>{const s=createSection(p,{source:b.dataset.copySection});appendSection(p,s.id);activateSection(p,s.id)}));
 $$('[data-delete-section]').forEach(b=>b.onclick=()=>{const s=p.sections.find(s=>s.id===b.dataset.deleteSection);confirm('Delete section '+s.name+'?','This removes its notes and every appearance from the song. You can undo it.',()=>change(()=>deleteSection(p,s.id)))});
 $$('[data-repeat-entry]').forEach(input=>input.onchange=()=>change(()=>{p.arrangement.find(e=>e.id===input.dataset.repeatEntry).repeats=+input.value}));
 $$('[data-remove-entry]').forEach(b=>b.onclick=()=>change(()=>{p.arrangement=p.arrangement.filter(e=>e.id!==b.dataset.removeEntry)}));
 $$('[data-move-entry]').forEach(b=>b.onclick=()=>{const entry=b.dataset.moveEntry;change(()=>moveEntry(p,entry,p.arrangement.findIndex(e=>e.id===entry)+Number(b.dataset.delta)));container.querySelector(`[data-entry="${entry}"]`)?.focus()});
 $$('[data-entrance-entry]').forEach(input=>input.onchange=()=>change(()=>{const e=p.arrangement.find(e=>e.id===input.dataset.entranceEntry);e.mutedTracks=input.checked?e.mutedTracks.filter(id=>id!==input.dataset.part):[...e.mutedTracks,input.dataset.part]}));
 $$('[data-entrances]').forEach(el=>el.ontoggle=()=>el.open?openEntries.add(el.dataset.entrances):openEntries.delete(el.dataset.entrances));
 $$('[data-form-jump]').forEach(b=>b.onclick=()=>{const el=container.querySelector(`[data-entry="${b.dataset.formJump}"]`);el?.scrollIntoView?.({behavior:'smooth',block:'center'});el?.focus()});
 let dragged=null;
 $$('[data-drag-entry]').forEach(b=>{b.ondragstart=e=>{dragged=b.dataset.dragEntry;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragged)};b.ondragend=()=>{dragged=null;$$('.drop-target').forEach(el=>el.classList.remove('drop-target'))}});
 $$('[data-entry]').forEach(el=>{el.ondragover=e=>{if(!dragged)return;e.preventDefault();e.dataTransfer.dropEffect='move';el.classList.add('drop-target')};el.ondragleave=()=>el.classList.remove('drop-target');el.ondrop=e=>{e.preventDefault();el.classList.remove('drop-target');if(!dragged||!p.arrangement.some(item=>item.id===dragged))return;const entry=dragged,to=p.arrangement.findIndex(item=>item.id===el.dataset.entry);change(()=>moveEntry(p,entry,to));container.querySelector(`[data-entry="${entry}"]`)?.focus();dragged=null}});
}
